package com.lmspilot.notification.domain; import jakarta.persistence.*;import java.io.*;import java.time.*;import java.util.*;
@Entity @Table(name="news_receipts") @IdClass(NewsReceiptId.class) public class NewsReceiptEntity{@Id public UUID newsId;@Id public UUID userId;@Column(nullable=false)public Instant readAt=Instant.now();public NewsReceiptEntity(){}} class NewsReceiptId implements Serializable{public UUID newsId;public UUID userId;public NewsReceiptId(){}public boolean equals(Object o){return o instanceof NewsReceiptId x&&Objects.equals(newsId,x.newsId)&&Objects.equals(userId,x.userId);}public int hashCode(){return Objects.hash(newsId,userId);}}
